  7	import lombok.RequiredArgsConstructor;
  8	import lombok.extern.slf4j.Slf4j;
  9	import org.springframework.http.ResponseEntity;
 10	import org.springframework.validation.annotation.Validated;
 11	import org.springframework.web.bind.annotation.*;
 12	
 13	/**
 14	 * 판매자 배송 정보 명령 컨트롤러
 15	 */
 16	@Slf4j
 17	@RestController
 18	@RequestMapping("/shipments/seller")
 19	@RequiredArgsConstructor
 20	public class SellerShipmentCommandController {
 21	
 22	    private final SellerShipmentCommandService sellerShipmentCommandService;
 23	
 24	    /**
 25	     * 판매자 배송 정보를 생성합니다.
 26	     *
 27	     * @param requestDto 판매자 배송 정보 DTO
 28	     * @return 생성된 배송 ID
 29	     */
 30	    @PostMapping
 31	    public ResponseEntity<Long> createSellerShipment(
 32	            @Validated @RequestBody SellerShipmentRequestDto requestDto
 33	    ) {
 34	        log.info("판매자 배송 정보 생성 요청: saleId={}, courier={}, trackingNumber={}",
 35	                requestDto.getSaleId(), requestDto.getCourier(), requestDto.getTrackingNumber());
 36	
 37	        try {
 38	            SellerShipment shipment = sellerShipmentCommandService.createSellerShipment(
 39	                    requestDto.getSaleId(),
 40	                    requestDto.getCourier(),
 41	                    requestDto.getTrackingNumber()
 42	            );
 43	
 44	            Long shipmentId = shipment.getId();
 45	            log.info("판매자 배송 정보 생성 완료: shipmentId={}, saleId={}",
 46	                    shipmentId, requestDto.getSaleId());
 47	
 48	            return ResponseEntity.ok(shipmentId);
 49	
 50	        } catch (ShipmentException e) {
 51	            log.error("판매자 배송 정보 생성 실패 (ShipmentException): saleId={}, code={}, message={}",
 52	                    requestDto.getSaleId(), e.getErrorCode().getCode(), e.getMessage());
 53	
 54	            return ResponseEntity
 55	                    .status(e.getErrorCode().getStatus())
 56	                    .build();
 57	
 58	        } catch (Exception e) {
 59	            log.error("판매자 배송 정보 생성 실패 (일반 예외): saleId={}, error={}",
 60	                    requestDto.getSaleId(), e.getMessage(), e);
 61	
 62	            return ResponseEntity.badRequest().build();
 63	        }
 64	    }
 65	
 66	    /**
 67	     * 판매자 배송 정보를 업데이트합니다.
 68	     *
 69	     * @param shipmentId 배송 ID
 70	     * @param requestDto 판매자 배송 정보 DTO
 71	     * @return 성공 응답
 72	     */
 73	    @PatchMapping("/{shipmentId}")
 74	    public ResponseEntity<Void> updateShipment(
 75	            @PathVariable Long shipmentId,
 76	            @Validated @RequestBody SellerShipmentRequestDto requestDto
 77	    ) {
 78	        log.info("판매자 배송 정보 업데이트 요청: shipmentId={}, courier={}, trackingNumber={}",
 79	                shipmentId, requestDto.getCourier(), requestDto.getTrackingNumber());
 80	
 81	        try {
 82	            sellerShipmentCommandService.updateShipment(
 83	                    shipmentId,
 84	                    requestDto.getCourier(),
 85	                    requestDto.getTrackingNumber()
 86	            );
 87	
 88	            log.info("판매자 배송 정보 업데이트 완료: shipmentId={}", shipmentId);
 89	            return ResponseEntity.ok().build();
 90	
 91	        } catch (ShipmentException e) {
 92	            log.error("판매자 배송 정보 업데이트 실패 (ShipmentException): shipmentId={}, code={}, message={}",
 93	                    shipmentId, e.getErrorCode().getCode(), e.getMessage());
 94	
 95	            return ResponseEntity
