  3	import com.fream.back.domain.sale.entity.Sale;
  4	import com.fream.back.domain.sale.entity.SaleStatus;
  5	import com.fream.back.domain.sale.repository.SaleRepository;
  6	import com.fream.back.domain.shipment.entity.SellerShipment;
  7	import com.fream.back.domain.shipment.entity.ShipmentStatus;
  8	import com.fream.back.domain.shipment.exception.ShipmentErrorCode;
  9	import com.fream.back.domain.shipment.exception.ShipmentException;
 10	import com.fream.back.domain.shipment.repository.SellerShipmentRepository;
 11	import com.fream.back.domain.warehouseStorage.service.command.WarehouseStorageCommandService;
 12	import lombok.RequiredArgsConstructor;
 13	import lombok.extern.slf4j.Slf4j;
 14	import org.springframework.stereotype.Service;
 15	import org.springframework.transaction.annotation.Transactional;
 16	
 17	/**
 18	 * 판매자 배송 관련 비즈니스 로직을 처리하는 서비스
 19	 */
 20	@Slf4j
 21	@Service
 22	@RequiredArgsConstructor
 23	public class SellerShipmentCommandService {
 24	
 25	    private final SellerShipmentRepository sellerShipmentRepository;
 26	    private final SaleRepository saleRepository;
 27	    private final WarehouseStorageCommandService warehouseStorageCommandService;
 28	
 29	    /**
 30	     * 판매에 대한 판매자 배송 정보를 생성합니다.
 31	     *
 32	     * @param saleId 판매 ID
 33	     * @param courier 택배사 이름
 34	     * @param trackingNumber 운송장 번호
 35	     * @return 생성된 판매자 배송 정보
 36	     * @throws ShipmentException 판매 정보를 찾을 수 없는 경우 또는 배송 정보 생성 실패 시
 37	     */
 38	    @Transactional
 39	    public SellerShipment createSellerShipment(Long saleId, String courier, String trackingNumber) {
 40	        log.info("판매자 배송 정보 생성 시작: saleId={}, courier={}, trackingNumber={}",
 41	                saleId, courier, trackingNumber);
 42	
 43	        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
 44	            log.warn("유효하지 않은 배송사 또는 운송장 번호: saleId={}", saleId);
 45	            throw new ShipmentException(ShipmentErrorCode.TRACKING_INFO_REQUIRED);
 46	        }
 47	
 48	        try {
 49	            // Sale 조회
 50	            Sale sale = saleRepository.findById(saleId)
 51	                    .orElseThrow(() -> new ShipmentException(
 52	                            ShipmentErrorCode.SALE_NOT_FOUND_FOR_SHIPMENT,
 53	                            "해당 Sale을 찾을 수 없습니다: " + saleId
 54	                    ));
 55	
 56	            log.debug("판매 정보 조회: saleId={}, sellerId={}, currentStatus={}",
 57	                    sale.getId(), sale.getSeller().getId(), sale.getStatus());
 58	
 59	            // SellerShipment 생성
 60	            SellerShipment shipment = SellerShipment.builder()
 61	                    .sale(sale)
 62	                    .courier(courier)
 63	                    .trackingNumber(trackingNumber)
 64	                    .status(ShipmentStatus.IN_TRANSIT) // 배송 중 상태로 설정
 65	                    .build();
 66	
 67	            // 연관관계 설정
 68	            sale.assignSellerShipment(shipment);
 69	
 70	            SellerShipment savedShipment = sellerShipmentRepository.save(shipment);
 71	            log.info("판매자 배송 정보 저장 완료: shipmentId={}, saleId={}",
 72	                    savedShipment.getId(), saleId);
 73	
 74	            // 창고 보관 상품인 경우 추가 처리
 75	            if (sale.isWarehouseStorage()) {
 76	                log.info("창고 보관 상품 처리: saleId={}", saleId);
 77	
 78	                // 창고 보관 데이터 생성
 79	                warehouseStorageCommandService.createSellerStorage(sale, sale.getSeller());
 80	
 81	                // 창고 보관 상태 업데이트
 82	                sale.updateStatus(SaleStatus.IN_STORAGE);
 83	                log.info("판매 상태 IN_STORAGE로 변경: saleId={}", saleId);
 84	            }
 85	
 86	            return savedShipment;
 87	
 88	        } catch (ShipmentException e) {
 89	            throw e;
 90	        } catch (Exception e) {
 91	            log.error("판매자 배송 정보 생성 실패: saleId={}, error={}", saleId, e.getMessage(), e);
 92	            throw new ShipmentException(
 93	                    ShipmentErrorCode.SALE_NOT_FOUND_FOR_SHIPMENT,
 94	                    "판매자 배송 정보 생성 중 오류 발생: " + e.getMessage(),
 95	                    e
 96	            );
 97	        }
 98	    }
 99	
100	    /**
101	     * 판매자 배송 정보를 업데이트합니다.
102	     *
103	     * @param shipmentId 배송 ID
104	     * @param courier 택배사 이름
105	     * @param trackingNumber 운송장 번호
106	     * @return 업데이트된 판매자 배송 정보
107	     * @throws ShipmentException 배송 정보를 찾을 수 없는 경우 또는 업데이트 실패 시
108	     */
109	    @Transactional
110	    public SellerShipment updateShipment(Long shipmentId, String courier, String trackingNumber) {
111	        log.info("판매자 배송 정보 업데이트: shipmentId={}, courier={}, trackingNumber={}",
112	                shipmentId, courier, trackingNumber);
113	
114	        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
115	            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
116	            throw new ShipmentException(ShipmentErrorCode.TRACKING_INFO_REQUIRED);
117	        }
118	
119	        try {
120	            SellerShipment sellerShipment = sellerShipmentRepository.findById(shipmentId)
121	                    .orElseThrow(() -> new ShipmentException(
122	                            ShipmentErrorCode.SELLER_SHIPMENT_NOT_FOUND,
123	                            "해당 Shipment를 찾을 수 없습니다: " + shipmentId
124	                    ));
125	
126	            log.debug("판매자 배송 정보 조회: shipmentId={}, saleId={}, currentStatus={}",
127	                    sellerShipment.getId(),
128	                    sellerShipment.getSale().getId(),
129	                    sellerShipment.getStatus());
130	
131	            sellerShipment.updateTrackingInfo(courier, trackingNumber);
132	            log.info("판매자 배송 정보 업데이트 완료: shipmentId={}", shipmentId);
133	
134	            return sellerShipment;
135	
136	        } catch (ShipmentException e) {
137	            throw e;
138	        } catch (Exception e) {
139	            log.error("판매자 배송 정보 업데이트 실패: shipmentId={}, error={}",
140	                    shipmentId, e.getMessage(), e);
141	            throw new ShipmentException(
142	                    ShipmentErrorCode.SELLER_SHIPMENT_NOT_FOUND,
143	                    "판매자 배송 정보 업데이트 중 오류 발생: " + e.getMessage(),
144	                    e
145	            );
146	        }
147	    }
148	}

